#include "mspa/psychology/learning.hpp"
#include <algorithm>
namespace mspa {namespace{
std::vector<std::string>canon(std::vector<std::string>x){std::sort(x.begin(),x.end());x.erase(std::unique(x.begin(),x.end()),x.end());return x;}
bool same(const std::vector<std::string>&a,const std::vector<std::string>&b){return canon(a)==canon(b);}
Result<void>update_pattern(AgentPsychState&a,ActionTypeId action,const std::vector<std::string>&tags,const std::string&outcome,bool occurred,PsychTime now,std::size_t max){auto it=std::find_if(a.learned_expectations.begin(),a.learned_expectations.end(),[&](const auto&e){return e.action==action&&e.outcome_tag==outcome&&same(e.context_tags,tags);});if(it==a.learned_expectations.end()){if(a.learned_expectations.size()>=max)return make_error(ErrorCode::QuotaExceeded,"learning pattern quota exceeded");LearnedExpectation e{};e.action=action;e.context_tags=tags;e.outcome_tag=outcome;e.attempts=1;e.successes=occurred?1u:0u;e.confidence=(static_cast<float>(e.successes)+1.0f)/3.0f;e.last_activation=now;a.learned_expectations.push_back(std::move(e));return{};}++it->attempts;if(occurred)++it->successes;it->confidence=(static_cast<float>(it->successes)+1.0f)/(static_cast<float>(it->attempts)+2.0f);it->last_activation=now;return{};}
}
void LearningSystem::report(AgentPsychState&a,ActionTypeId act,bool ok)const{LearningReport r{};r.action=act;r.success=ok;r.now=a.last_processed_time;(void)report(a,r);}
Result<void>LearningSystem::report(AgentPsychState&a,const LearningReport&r,std::size_t max)const{if(!r.action.valid())return make_error(ErrorCode::InvalidArgument,"invalid learned action");const auto tags=canon(r.context_tags);auto q=update_pattern(a,r.action,tags,"success",r.success,r.now,max);if(!q)return *q.error_if();q=update_pattern(a,r.action,tags,"failure",!r.success,r.now,max);if(!q)return *q.error_if();for(const auto&o:r.outcome_tags){if(o.empty()||o=="success"||o=="failure")continue;q=update_pattern(a,r.action,tags,o,true,r.now,max);if(!q)return *q.error_if();}return {};}
float LearningSystem::expected_success(const AgentPsychState&a,ActionTypeId act)const noexcept{return expected_success(a,act,{});}float LearningSystem::expected_success(const AgentPsychState&a,ActionTypeId act,const std::vector<std::string>&ctx)const noexcept{return expected_outcome(a,act,ctx,"success");}float LearningSystem::expected_outcome(const AgentPsychState&a,ActionTypeId act,const std::vector<std::string>&ctx,const std::string&o)const noexcept{const auto tags=canon(ctx);float sum=0,weight=0;for(const auto&e:a.learned_expectations){if(e.action!=act||e.outcome_tag!=o)continue;float w=same(e.context_tags,tags)?2.0f:(e.context_tags.empty()?0.75f:0.0f);if(w>0){sum+=w*e.confidence;weight+=w;}}return weight>0?sum/weight:0.5f;}}
